#include <stdio.h>
#include <string.h>
#include <stdlib.h>

typedef unsigned int ZSTD_bool;
size_t ZSTD_compress(void* dst, size_t dstCapacity, const void* src, size_t srcSize, int compressionLevel);
size_t ZSTD_decompress(void* dst, size_t dstCapacity, const void* src, size_t compressedSize);
size_t ZSTD_compressBound(size_t srcSize);
unsigned ZSTD_isError(size_t code);
const char* ZSTD_getErrorName(size_t code);
unsigned ZSTD_versionNumber(void);

int main(void) {
    printf("version=%u\n", ZSTD_versionNumber());
    const char* src = "hello hello hello hello";
    size_t srcLen = strlen(src);
    size_t bound = ZSTD_compressBound(srcLen);
    char* dst = malloc(bound);
    size_t result = ZSTD_compress(dst, bound, src, srcLen, 3);
    printf("compressed size=%zu error=%u\n", result, ZSTD_isError(result));
    char out[1024];
    size_t dec = ZSTD_decompress(out, sizeof(out), dst, result);
    printf("decompressed size=%zu error=%u\n", dec, ZSTD_isError(dec));
    out[dec] = 0;
    printf("out=%s\n", out);
    return 0;
}
EOF
gcc test_link.c -L/usr/lib/x86_64-linux-gnu -l:libzstd.so.1 -o test_link && ./test_link

