cat > /workspace/src/fmt.c <<'EOF'
#include <stdio.h>
#include <string.h>
#include "fmt.h"

/* Format a size in a human-readable way similar to zstd.
   Writes the result to buf (of size bufSize). Returns number of bytes written.
   Special cases:
   - size < 1024: "%6llu B"
   - size is exact power of 1024 unit (size == unit_size): "%6.3f UNIT" (e.g., " 1.000 KiB")
   - else pick unit U such that size/U is in [1, 1024): format depends on value.
     value < 10 -> "%6.2f UNIT"
     value < 100 -> "%6.1f UNIT"
     else -> "%6.0f UNIT"
*/
void fmt_readable_size(char *buf, size_t bufSize, unsigned long long size) {
    if (size < 1024ULL) {
        snprintf(buf, bufSize, "%6llu B", size);
        return;
    }
    static const char * const units[] = {"KiB", "MiB", "GiB", "TiB", "PiB"};
    int idx = -1;
    unsigned long long divisor = 1ULL;
    unsigned long long cur = size;
    while (cur >= 1024ULL && idx < 4) {
        divisor *= 1024ULL;
        cur /= 1024ULL;
        idx++;
    }
