}

/* Prompt user overwrite confirmation. Returns 1 if overwrite accepted. */
static int prompt_overwrite(const char *dst) {
    if (force_flag) return 1;
    if (!file_exists(dst)) return 1;
    if (!isatty(fileno(stdin))) {
        fprintf(stderr, "zstd: %s already exists; not overwritten  \n", dst);
        return 0;
    }
    fprintf(stderr, "zstd: %s already exists; overwrite (y/n) ? ", dst);
    int c = fgetc(stdin);
    int first = c;
    while (c != '\n' && c != EOF) c = fgetc(stdin);
    if (first == 'y' || first == 'Y') return 1;
    fprintf(stderr, "Not overwritten  \n \n");
    return 0;
}

/* Determine if filename has zstd-ish suffix */
static int has_zstd_suffix(const char *name) {
    size_t n = strlen(name);
    const char *sfx[] = {".zst", ".tzst", ".gz", ".tgz", ".xz", ".txz", ".lz4", ".tlz4", NULL};
    for (int i = 0; sfx[i]; i++) {
        size_t s = strlen(sfx[i]);
        if (n > s && strcmp(name + n - s, sfx[i]) == 0) return i + 1;
    }
    return 0;
}

/* Strip known suffix from filename; returns allocated string of basename without suffix,
   or NULL if no known suffix. */
static char *strip_suffix(const char *name) {
    size_t n = strlen(name);
    const char *sfx[] = {".zst", ".tzst", ".gz", ".tgz", ".xz", ".txz", ".lz4", ".tlz4", NULL};
    const char *replace[] = {"", ".tar", "", ".tar", "", ".tar", "", ".tar", NULL};
    for (int i = 0; sfx[i]; i++) {
        size_t s = strlen(sfx[i]);
        if (n > s && strcmp(name + n - s, sfx[i]) == 0) {
            size_t baseLen = n - s;
            const char *rep = replace[i];
            size_t rl = strlen(rep);
            char *out = malloc(baseLen + rl + 1);
            if (!out) return NULL;
            memcpy(out, name, baseLen);
            memcpy(out + baseLen, rep, rl);
            out[baseLen + rl] = 0;
            return out;
        }
    }
    return NULL;
}

/* ------------ Dictionary loading ------------ */
static unsigned char *dict_data = NULL;
static size_t dict_size = 0;

static int load_dictionary(void) {
    if (!dict_path) return 0;
    FILE *f = fopen(dict_path, "rb");
    if (!f) {
        fprintf(stderr, "zstd: can't open dictionary %s : %s \n",
                dict_path, strerror(errno));
        return -1;
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (sz < 0) { fclose(f); return -1; }
    dict_data = malloc((size_t)sz);
    if (!dict_data) { fclose(f); return -1; }
    if (fread(dict_data, 1, (size_t)sz, f) != (size_t)sz) {
        fclose(f); free(dict_data); dict_data = NULL; return -1;
    }
    fclose(f);
    dict_size = (size_t)sz;
    return 0;
}

/* ------------ Compression ------------ */
/* Compress stream from `in` (FILE*) to `out` (FILE*).
   `src_size_known` != 0 means srcSize is known and should be pledged.
   Returns 0 on success, -1 on error.
   On success, writes source size to *out_src and compressed size to *out_dst. */
static int compress_stream(FILE *in, FILE *out,
                            int src_size_known, unsigned long long src_size,
                            unsigned long long *out_src,
                            unsigned long long *out_dst) {
    ZSTD_CCtx *cctx = ZSTD_createCCtx();
    if (!cctx) {
        fprintf(stderr, "zstd: error : could not allocate context \n");
        return -1;
    }
    int level = comp_level;
    if (fast_level > 0) level = -fast_level;
    ZSTD_CCtx_setParameter(cctx, ZSTD_c_compressionLevel, level);
    if (no_checksum) ZSTD_CCtx_setParameter(cctx, ZSTD_c_checksumFlag, 0);
    else ZSTD_CCtx_setParameter(cctx, ZSTD_c_checksumFlag, 1);
    if (no_dictID) ZSTD_CCtx_setParameter(cctx, ZSTD_c_dictIDFlag, 0);
    if (long_enabled) {
        ZSTD_CCtx_setParameter(cctx, ZSTD_c_enableLongDistanceMatching, 1);
        if (long_log > 0) ZSTD_CCtx_setParameter(cctx, ZSTD_c_windowLog, long_log);
    }
    if (nb_workers > 0 && !single_thread) {
        ZSTD_CCtx_setParameter(cctx, ZSTD_c_nbWorkers, nb_workers);
    }
    if (src_size_known) {
        ZSTD_CCtx_setPledgedSrcSize(cctx, src_size);
    }
    if (dict_data && dict_size) {
        ZSTD_CCtx_loadDictionary(cctx, dict_data, dict_size);
    }

    size_t inBufSize = ZSTD_CStreamInSize();
    size_t outBufSize = ZSTD_CStreamOutSize();
    void *inBuf = malloc(inBufSize);
    void *outBuf = malloc(outBufSize);
    if (!inBuf || !outBuf) {
        fprintf(stderr, "zstd: memory allocation error \n");
        free(inBuf); free(outBuf); ZSTD_freeCCtx(cctx); return -1;
    }
    unsigned long long total_in = 0, total_out = 0;
    int status = 0;
    int done = 0;
    while (!done) {
        size_t n = fread(inBuf, 1, inBufSize, in);
        int last = feof(in) != 0;
        ZSTD_inBuffer input = { inBuf, n, 0 };
        ZSTD_EndDirective mode = last ? ZSTD_e_end : ZSTD_e_continue;
        total_in += n;
        int finished;
        do {
            ZSTD_outBuffer output = { outBuf, outBufSize, 0 };
            size_t r = ZSTD_compressStream2(cctx, &output, &input, mode);
            if (ZSTD_isError(r)) {
                fprintf(stderr, "zstd: error compressing: %s \n",
                        ZSTD_getErrorName(r));
                status = -1;
                done = 1;
                break;
            }
            if (output.pos > 0) {
                if (fwrite(outBuf, 1, output.pos, out) != output.pos) {
                    fprintf(stderr, "zstd: error writing output: %s \n",
                            strerror(errno));
                    status = -1;
                    done = 1;
                    break;
                }
                total_out += output.pos;
            }
            finished = last ? (r == 0) : (input.pos == input.size);
        } while (!finished);
        if (last) done = 1;
    }
    free(inBuf); free(outBuf); ZSTD_freeCCtx(cctx);
    if (out_src) *out_src = total_in;
    if (out_dst) *out_dst = total_out;
    return status;
}

/* ------------ Decompression ------------ */
static int decompress_stream(FILE *in, FILE *out,
                              unsigned long long *out_src_compressed,
                              unsigned long long *out_dst_uncompressed,
                              const char *src_name) {
    ZSTD_DCtx *dctx = ZSTD_createDCtx();
    if (!dctx) {
        fprintf(stderr, "zstd: error creating dctx \n");
        return -1;
    }
    if (memory_limit_mb > 0) {
        int wl = 0, mb = memory_limit_mb;
        while ((1 << wl) < mb) wl++;
        ZSTD_DCtx_setParameter(dctx, ZSTD_d_windowLogMax, wl + 20);
    }
    if (dict_data && dict_size) {
        ZSTD_DCtx_loadDictionary(dctx, dict_data, dict_size);
    }
    size_t inBufSize = ZSTD_DStreamInSize();
    size_t outBufSize = ZSTD_DStreamOutSize();
    unsigned char *inBuf = malloc(inBufSize);
    unsigned char *outBuf = malloc(outBufSize);
    if (!inBuf || !outBuf) {
        fprintf(stderr, "zstd: memory allocation error \n");
        free(inBuf); free(outBuf); ZSTD_freeDCtx(dctx); return -1;
    }
    unsigned long long total_in = 0, total_out = 0;
    int status = 0;
    int first_read = 1;
    int unsupported = 0;
    ZSTD_inBuffer input = { inBuf, 0, 0 };
    int need_new_frame = 1;
    size_t last_ret = 0;
    while (1) {
        if (input.pos >= input.size) {
            /* refill */
            size_t n = fread(inBuf, 1, inBufSize, in);
            if (n == 0) {
                if (!need_new_frame && last_ret != 0) {
                    fprintf(stderr, "zstd: %s: unexpected end of file \n",
                            src_name ? src_name : "stdin");
                    status = -1;
                }
                break;
            }
            input.src = inBuf;
            input.size = n;
            input.pos = 0;
            total_in += n;
            if (first_read) {
                first_read = 0;
                /* Check magic for zstd */
                if (n >= 4) {
                    unsigned magic = (unsigned)inBuf[0] |
                                     ((unsigned)inBuf[1] << 8) |
                                     ((unsigned)inBuf[2] << 16) |
                                     ((unsigned)inBuf[3] << 24);
                    unsigned sk = magic & ZSTD_MAGIC_SKIPPABLE_MASK;
                    if (magic != ZSTD_MAGICNUMBER && sk != ZSTD_MAGIC_SKIPPABLE_START) {
                        fprintf(stderr, "zstd: %s: unsupported format \n",
                                src_name ? src_name : "stdin");
                        unsupported = 1;
                        status = -1;
                        break;
                    }
                }
            }
        }
        ZSTD_outBuffer output = { outBuf, outBufSize, 0 };
        size_t r = ZSTD_decompressStream(dctx, &output, &input);
        if (ZSTD_isError(r)) {
            fprintf(stderr, "zstd: %s: %s \n",
                    src_name ? src_name : "stdin",
                    ZSTD_getErrorName(r));
            status = -1;
            break;
        }
        last_ret = r;
        need_new_frame = (r == 0);
        if (output.pos > 0) {
            if (out) {
                if (fwrite(outBuf, 1, output.pos, out) != output.pos) {
                    fprintf(stderr, "zstd: error writing output: %s \n",
                            strerror(errno));
                    status = -1;
                    break;
                }
            }
            total_out += output.pos;
        }
    }
    free(inBuf); free(outBuf); ZSTD_freeDCtx(dctx);
    if (out_src_compressed) *out_src_compressed = total_in;
    if (out_dst_uncompressed) *out_dst_uncompressed = total_out;
    (void)unsupported;
    return status;
}

/* ------------ Print per-file progress summary ------------ */
static void print_progress_compress(const char *name, const char *out_name,
                                     unsigned long long src, unsigned long long dst) {
    char src_buf[32];
    char dst_buf[32];
    fmt_readable_size(src_buf, sizeof(src_buf), src);
    fmt_readable_size(dst_buf, sizeof(dst_buf), dst);
    if (verbosity < 2) return;
    if (src == 0) {
        fprintf(stderr, "%-20s :  (%s =>%s, %s) \n",
                name, src_buf, dst_buf, out_name);
    } else {
        double pct = 100.0 * (double)dst / (double)src;
        fprintf(stderr, "%-20s :%6.2f%%   (%s =>%s, %s) \n",
                name, pct, src_buf, dst_buf, out_name);
    }
}

static void print_progress_decompress(const char *name,
                                       unsigned long long dst) {
    if (verbosity < 2) return;
    fprintf(stderr, "%-20s : %llu bytes \n", name, dst);
}

/* ------------ Derive output name for compression ------------ */
static char *derive_comp_out(const char *input_name) {
    size_t n = strlen(input_name);
    char *out = malloc(n + 8);
    if (!out) return NULL;
    snprintf(out, n + 8, "%s.zst", input_name);
    return out;
}

/* ------------ Operate on one file ------------ */
static int operate_compress_file(const char *in_name) {
    FILE *in = NULL;
    const char *src_name = in_name;
    int is_stdin = (strcmp(in_name, "-") == 0);
    int src_size_known = 0;
    unsigned long long src_size = 0;
    if (is_stdin) {
        in = stdin;
        src_name = STDIN_NAME;
        if (stream_size >= 0) { src_size_known = 1; src_size = (unsigned long long)stream_size; }
    } else {
        struct stat st;
        if (stat(in_name, &st) < 0) {
            fprintf(stderr, "zstd: can't stat %s : %s -- ignored \n",
                    in_name, strerror(errno));
            return -1;
        }
        if (S_ISDIR(st.st_mode)) {
            fprintf(stderr, "zstd: %s is a directory -- ignored \n", in_name);
            return -1;
        }
        in = fopen(in_name, "rb");
        if (!in) {
            fprintf(stderr, "zstd: can't open %s : %s \n", in_name, strerror(errno));
            return -1;
        }
        if (S_ISREG(st.st_mode)) {
            src_size_known = 1;
            src_size = (unsigned long long)st.st_size;
        }
    }
    /* Determine output */
    FILE *out = NULL;
    char *derived = NULL;
    const char *out_name = NULL;
    int use_stdout = to_stdout;
    if (is_stdin && !output_file && !use_stdout) use_stdout = 1;
    if (use_stdout) {
        out = stdout;
        out_name = STDOUT_NAME;
    } else if (output_file) {
        out_name = output_file;
    } else {
        derived = derive_comp_out(in_name);
        out_name = derived;
    }
    if (!use_stdout) {
        if (!prompt_overwrite(out_name)) {
            if (in != stdin) fclose(in);
            free(derived);
            return -1;
        }
        out = fopen(out_name, "wb");
        if (!out) {
            fprintf(stderr, "zstd: can't open %s : %s \n", out_name, strerror(errno));
            if (in != stdin) fclose(in);
            free(derived);
            return -1;
        }
    } else {
        if (isatty(fileno(stdout)) && !force_flag) {
            fprintf(stderr,
                    "zstd: stdout is a console, aborting (use -f to force) \n");
            if (in != stdin) fclose(in);
            free(derived);
            return -1;
        }
    }
    unsigned long long osrc = 0, odst = 0;
    int rc = compress_stream(in, out, src_size_known, src_size, &osrc, &odst);
    if (in != stdin) fclose(in);
    if (out && out != stdout) fclose(out);
    if (rc == 0) {
        print_progress_compress(src_name, out_name, osrc, odst);
        if (rm_explicit && !is_stdin && !use_stdout) {
            if (unlink(in_name) != 0) {
                fprintf(stderr, "zstd: couldn't remove source %s : %s \n",
                        in_name, strerror(errno));
            }
        }
    } else {
        if (!use_stdout && out_name) unlink(out_name);
    }
    free(derived);
    return rc;
}

static int operate_decompress_file(const char *in_name) {
    FILE *in = NULL;
    const char *src_name = in_name;
    int is_stdin = (strcmp(in_name, "-") == 0);
    char *derived = NULL;
    const char *out_name = NULL;
    FILE *out = NULL;
    int use_stdout = to_stdout;
    if (is_stdin) {
        in = stdin;
        src_name = STDIN_NAME;
        if (!output_file) use_stdout = 1;
    } else {
        struct stat st;
        if (stat(in_name, &st) < 0) {
            fprintf(stderr, "zstd: can't stat %s : %s -- ignored \n",
                    in_name, strerror(errno));
            return -1;
        }
        if (S_ISDIR(st.st_mode)) {
            fprintf(stderr, "zstd: %s is a directory -- ignored \n", in_name);
            return -1;
        }
        in = fopen(in_name, "rb");
        if (!in) {
            fprintf(stderr, "zstd: can't open %s : %s \n", in_name, strerror(errno));
            return -1;
        }
    }
    if (use_stdout) {
        out = stdout;
        out_name = STDOUT_NAME;
    } else if (output_file) {
        out_name = output_file;
    } else {
        derived = strip_suffix(in_name);
        if (!derived) {
            fprintf(stderr,
                "zstd: %s: unknown suffix (.zst/.tzst/.gz/.tgz expected). "
                "Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n",
                in_name);
            if (in != stdin) fclose(in);
            return -1;
        }
        out_name = derived;
    }
    if (!test_mode && !use_stdout) {
        if (!prompt_overwrite(out_name)) {
            if (in != stdin) fclose(in);
            free(derived);
            return -1;
        }
        out = fopen(out_name, "wb");
        if (!out) {
            fprintf(stderr, "zstd: can't open %s : %s \n", out_name, strerror(errno));
            if (in != stdin) fclose(in);
            free(derived);
            return -1;
        }
    }
    if (test_mode) {
        out = NULL;
        out_name = NULL;
    }
    unsigned long long osrc = 0, odst = 0;
    int rc = decompress_stream(in, out, &osrc, &odst, src_name);
    if (in != stdin) fclose(in);
    if (out && out != stdout) fclose(out);
    if (rc == 0) {
        if (test_mode) {
            print_progress_decompress(src_name, odst);
        } else if (!use_stdout) {
            print_progress_decompress(src_name, odst);
            if (rm_explicit && !is_stdin) {
                if (unlink(in_name) != 0) {
                    fprintf(stderr, "zstd: couldn't remove source %s : %s \n",
                            in_name, strerror(errno));
                }
            }
        }
    } else {
        if (!test_mode && !use_stdout && out_name) unlink(out_name);
    }
    free(derived);
    return rc;
}

/* ------------ List mode ------------ */
static int list_one(const char *name) {
    FILE *f = fopen(name, "rb");
    if (!f) {
        fprintf(stderr, "zstd: can't open %s : %s \n", name, strerror(errno));
        return -1;
    }
    unsigned long long compressed = 0;
    unsigned long long uncompressed = 0;
    unsigned frames = 0;
    unsigned skips = 0;
    int has_check = 0;
    unsigned char hdr[18];
    while (1) {
        size_t n = fread(hdr, 1, 4, f);
        if (n == 0) break;
        if (n < 4) { fclose(f); return -1; }
        compressed += n;
        unsigned magic = hdr[0] | (hdr[1] << 8) | (hdr[2] << 16) | (hdr[3] << 24);
        if ((magic & ZSTD_MAGIC_SKIPPABLE_MASK) == ZSTD_MAGIC_SKIPPABLE_START) {
            unsigned char szBuf[4];
            if (fread(szBuf, 1, 4, f) != 4) { fclose(f); return -1; }
            compressed += 4;
            unsigned sz = szBuf[0] | (szBuf[1]<<8) | (szBuf[2]<<16) | (szBuf[3]<<24);
            /* skip sz bytes */
            if (fseek(f, sz, SEEK_CUR) != 0) { fclose(f); return -1; }
            compressed += sz;
            skips++;
            continue;
        }
        if (magic != ZSTD_MAGICNUMBER) {
            fprintf(stderr, "zstd: %s: not in zstd format \n", name);
            fclose(f); return -1;
        }
        /* Read more header bytes to decode */
        size_t toRead = 14; /* remaining bytes, max */
        if (fread(hdr + 4, 1, toRead, f) < 1) { fclose(f); return -1; }
        /* Determine header length */
        ZSTD_frameHeader zfh;
        size_t hret = ZSTD_getFrameHeader(&zfh, hdr, 4 + toRead);
        if (ZSTD_isError(hret) || hret > 0) {
            fprintf(stderr, "zstd: %s: error parsing frame header \n", name);
            fclose(f); return -1;
        }
        /* Skip remaining frame bytes by incremental decode using the known frameContentSize/block reading.
           But simpler: compute the rest using ZSTD_findFrameCompressedSize by reading the full frame. */
        /* Seek back to frame start and read whole frame */
        long frame_start = ftell(f) - (long)(4 + toRead);
        fseek(f, frame_start, SEEK_SET);
        /* Read all remaining bytes of file */
        long cur = ftell(f);
        fseek(f, 0, SEEK_END);
        long end = ftell(f);
        size_t rem = (size_t)(end - cur);
        fseek(f, cur, SEEK_SET);
        unsigned char *buf = malloc(rem);
        if (!buf) { fclose(f); return -1; }
        if (fread(buf, 1, rem, f) != rem) { free(buf); fclose(f); return -1; }
        size_t framesz = ZSTD_findFrameCompressedSize(buf, rem);
        if (ZSTD_isError(framesz)) {
            fprintf(stderr, "zstd: %s: error parsing frame: %s \n", name,
                    ZSTD_getErrorName(framesz));
            free(buf); fclose(f); return -1;
        }
        /* fix: compressed was double-incremented; reset and recompute */
        frames++;
        compressed = compressed - (4 + toRead);
        compressed += framesz;
        if (zfh.frameContentSize != ZSTD_CONTENTSIZE_UNKNOWN) {
            uncompressed += zfh.frameContentSize;
        }
        has_check |= zfh.checksumFlag;
        /* Seek past the frame */
        fseek(f, frame_start + (long)framesz, SEEK_SET);
        free(buf);
    }
    fclose(f);
    char cbuf[32], ubuf[32];
    fmt_readable_size(cbuf, sizeof(cbuf), compressed);
    fmt_readable_size(ubuf, sizeof(ubuf), uncompressed);
    double ratio = uncompressed ? (double)uncompressed / (double)compressed : 0.0;
    const char *chk = has_check ? "XXH64" : "None ";
    printf("%6u %6u  %s  %s  %5.3f  %s  %s\n",
           frames, skips, cbuf, ubuf, ratio, chk, name);
    return 0;
}

static int do_list(int argc_files, char **files) {
    if (argc_files == 0) {
        fprintf(stderr, "zstd: --list does not support reading from standard input \n");
        fprintf(stderr, "No files given \n");
        return 1;
    }
    printf("Frames  Skips  Compressed  Uncompressed  Ratio  Check  Filename\n");
    int err = 0;
    for (int i = 0; i < argc_files; i++) {
        if (list_one(files[i]) != 0) err = 1;
    }
    return err;
}

/* ------------ Argument parsing ------------ */
static int parse_uint(const char *s, int *out) {
    char *end;
    long v = strtol(s, &end, 10);
    if (end == s || *end != 0 || v < 0 || v > INT_MAX) return -1;
    *out = (int)v;
    return 0;
}

int main(int argc, char **argv) {
    (void)PROG;
    if (argc < 1) return 1;
    /* Detect unzstd / zstdcat invocation from argv[0] */
    const char *bn = strrchr(argv[0], '/');
    bn = bn ? bn + 1 : argv[0];
    if (strstr(bn, "unzstd")) decompress_mode = 1;
    if (strstr(bn, "zstdcat")) { decompress_mode = 1; to_stdout = 1; }
    if (strstr(bn, "zstdmt")) { nb_workers = 0; /* all cores */ }

    int mode_dict_train = 0;
    (void)mode_dict_train;
    int after_dash = 0;
