            if (*opt == 0) { after_dash = 1; continue; }
            if (strcmp(opt, "version") == 0) { print_version(stdout); return 0; }
            if (strcmp(opt, "help") == 0) { print_full_help(stdout); return 0; }
            if (strcmp(opt, "decompress") == 0 || strcmp(opt, "uncompress") == 0) { decompress_mode = 1; continue; }
            if (strcmp(opt, "stdout") == 0 || strcmp(opt, "to-stdout") == 0) { to_stdout = 1; keep = 1; continue; }
            if (strcmp(opt, "keep") == 0) { keep = 1; rm_explicit = 0; continue; }
            if (strcmp(opt, "rm") == 0) { rm_explicit = 1; continue; }
            if (strcmp(opt, "force") == 0) { force_flag = 1; continue; }
            if (strcmp(opt, "verbose") == 0) { verbosity++; continue; }
            if (strcmp(opt, "quiet") == 0) { verbosity--; continue; }
            if (strcmp(opt, "test") == 0) { test_mode = 1; decompress_mode = 1; continue; }
            if (strcmp(opt, "ultra") == 0) { ultra = 1; continue; }
