}

/* Utility to test if a file exists */
static int file_exists(const char *path) {
    struct stat st;
    return stat(path, &st) == 0;
}

/* Prompt user overwrite confirmation. Returns 1 if overwrite accepted. */
static int prompt_overwrite(const char *dst) {
    if (force_flag) return 1;
    if (!file_exists(dst)) return 1;
    if (!isatty(fileno(stdin))) {
        fprintf(stderr, "zstd: %s already exists; not overwritten  \n", dst);
        return 0;
    }
    fprintf(stderr, "zstd: %s already exists; overwrite (y/n) ? ", dst);
    int c = fgetc(stdin);
    int first = c;
    while (c != '\n' && c != EOF) c = fgetc(stdin);
    if (first == 'y' || first == 'Y') return 1;
    fprintf(stderr, "Not overwritten  \n \n");
    return 0;
}

/* Determine if filename has zstd-ish suffix */
static int has_zstd_suffix(const char *name) {
    size_t n = strlen(name);
    const char *sfx[] = {".zst", ".tzst", ".gz", ".tgz", ".xz", ".txz", ".lz4", ".tlz4", NULL};
    for (int i = 0; sfx[i]; i++) {
        size_t s = strlen(sfx[i]);
        if (n > s && strcmp(name + n - s, sfx[i]) == 0) return i + 1;
    }
    return 0;
}

/* Strip known suffix from filename; returns allocated string of basename without suffix,
   or NULL if no known suffix. */
static char *strip_suffix(const char *name) {
    size_t n = strlen(name);
    const char *sfx[] = {".zst", ".tzst", ".gz", ".tgz", ".xz", ".txz", ".lz4", ".tlz4", NULL};
    const char *replace[] = {"", ".tar", "", ".tar", "", ".tar", "", ".tar", NULL};
    for (int i = 0; sfx[i]; i++) {
        size_t s = strlen(sfx[i]);
        if (n > s && strcmp(name + n - s, sfx[i]) == 0) {
            size_t baseLen = n - s;
            const char *rep = replace[i];
            size_t rl = strlen(rep);
            char *out = malloc(baseLen + rl + 1);
            if (!out) return NULL;
            memcpy(out, name, baseLen);
            memcpy(out + baseLen, rep, rl);
            out[baseLen + rl] = 0;
            return out;
        }
    }
    return NULL;
}

/* ------------ Dictionary loading ------------ */
static unsigned char *dict_data = NULL;
static size_t dict_size = 0;

static int load_dictionary(void) {
    if (!dict_path) return 0;
    FILE *f = fopen(dict_path, "rb");
    if (!f) {
        fprintf(stderr, "zstd: can't open dictionary %s : %s \n",
                dict_path, strerror(errno));
        return -1;
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (sz < 0) { fclose(f); return -1; }
    dict_data = malloc((size_t)sz);
    if (!dict_data) { fclose(f); return -1; }
    if (fread(dict_data, 1, (size_t)sz, f) != (size_t)sz) {
        fclose(f); free(dict_data); dict_data = NULL; return -1;
    }
    fclose(f);
    dict_size = (size_t)sz;
    return 0;
}

/* ------------ Compression ------------ */
/* Compress stream from `in` (FILE*) to `out` (FILE*).
   `src_size_known` != 0 means srcSize is known and should be pledged.
   Returns 0 on success, -1 on error.
   On success, writes source size to *out_src and compressed size to *out_dst. */
static int compress_stream(FILE *in, FILE *out,
                            int src_size_known, unsigned long long src_size,
                            unsigned long long *out_src,
                            unsigned long long *out_dst) {
    ZSTD_CCtx *cctx = ZSTD_createCCtx();
    if (!cctx) {
        fprintf(stderr, "zstd: error : could not allocate context \n");
        return -1;
    }
    int level = comp_level;
    if (fast_level > 0) level = -fast_level;
    ZSTD_CCtx_setParameter(cctx, ZSTD_c_compressionLevel, level);
    if (no_checksum) ZSTD_CCtx_setParameter(cctx, ZSTD_c_checksumFlag, 0);
    else ZSTD_CCtx_setParameter(cctx, ZSTD_c_checksumFlag, 1);
    if (no_dictID) ZSTD_CCtx_setParameter(cctx, ZSTD_c_dictIDFlag, 0);
    if (long_enabled) {
        ZSTD_CCtx_setParameter(cctx, ZSTD_c_enableLongDistanceMatching, 1);
        if (long_log > 0) ZSTD_CCtx_setParameter(cctx, ZSTD_c_windowLog, long_log);
    }
    if (nb_workers > 0 && !single_thread) {
        ZSTD_CCtx_setParameter(cctx, ZSTD_c_nbWorkers, nb_workers);
    }
    if (src_size_known) {
        ZSTD_CCtx_setPledgedSrcSize(cctx, src_size);
    }
    if (dict_data && dict_size) {
        ZSTD_CCtx_loadDictionary(cctx, dict_data, dict_size);
    }

    size_t inBufSize = ZSTD_CStreamInSize();
    size_t outBufSize = ZSTD_CStreamOutSize();
    void *inBuf = malloc(inBufSize);
    void *outBuf = malloc(outBufSize);
    if (!inBuf || !outBuf) {
        fprintf(stderr, "zstd: memory allocation error \n");
        free(inBuf); free(outBuf); ZSTD_freeCCtx(cctx); return -1;
    }
    unsigned long long total_in = 0, total_out = 0;
    int status = 0;
    int done = 0;
    while (!done) {
        size_t n = fread(inBuf, 1, inBufSize, in);
        int last = feof(in) != 0;
        ZSTD_inBuffer input = { inBuf, n, 0 };
        ZSTD_EndDirective mode = last ? ZSTD_e_end : ZSTD_e_continue;
        total_in += n;
        int finished;
        do {
            ZSTD_outBuffer output = { outBuf, outBufSize, 0 };
            size_t r = ZSTD_compressStream2(cctx, &output, &input, mode);
            if (ZSTD_isError(r)) {
                fprintf(stderr, "zstd: error compressing: %s \n",
                        ZSTD_getErrorName(r));
                status = -1;
                done = 1;
                break;
            }
            if (output.pos > 0) {
                if (fwrite(outBuf, 1, output.pos, out) != output.pos) {
                    fprintf(stderr, "zstd: error writing output: %s \n",
                            strerror(errno));
                    status = -1;
                    done = 1;
                    break;
                }
                total_out += output.pos;
            }
            finished = last ? (r == 0) : (input.pos == input.size);
        } while (!finished);
        if (last) done = 1;
    }
    free(inBuf); free(outBuf); ZSTD_freeCCtx(cctx);
    if (out_src) *out_src = total_in;
    if (out_dst) *out_dst = total_out;
    return status;
}

/* ------------ Decompression ------------ */
static int decompress_stream(FILE *in, FILE *out,
                              unsigned long long *out_src_compressed,
                              unsigned long long *out_dst_uncompressed,
                              const char *src_name) {
    ZSTD_DCtx *dctx = ZSTD_createDCtx();
    if (!dctx) {
        fprintf(stderr, "zstd: error creating dctx \n");
        return -1;
    }
    if (memory_limit_mb > 0) {
        int wl = 0, mb = memory_limit_mb;
        while ((1 << wl) < mb) wl++;
        ZSTD_DCtx_setParameter(dctx, ZSTD_d_windowLogMax, wl + 20);
    }
    if (dict_data && dict_size) {
        ZSTD_DCtx_loadDictionary(dctx, dict_data, dict_size);
    }
    size_t inBufSize = ZSTD_DStreamInSize();
    size_t outBufSize = ZSTD_DStreamOutSize();
    unsigned char *inBuf = malloc(inBufSize);
    unsigned char *outBuf = malloc(outBufSize);
    if (!inBuf || !outBuf) {
        fprintf(stderr, "zstd: memory allocation error \n");
        free(inBuf); free(outBuf); ZSTD_freeDCtx(dctx); return -1;
    }
    unsigned long long total_in = 0, total_out = 0;
    int status = 0;
    int first_read = 1;
    int unsupported = 0;
    ZSTD_inBuffer input = { inBuf, 0, 0 };
    int need_new_frame = 1;
    size_t last_ret = 0;
    while (1) {
        if (input.pos >= input.size) {
            /* refill */
            size_t n = fread(inBuf, 1, inBufSize, in);
            if (n == 0) {
                if (!need_new_frame && last_ret != 0) {
                    fprintf(stderr, "zstd: %s: unexpected end of file \n",
                            src_name ? src_name : "stdin");
                    status = -1;
                }
                break;
            }
            input.src = inBuf;
            input.size = n;
            input.pos = 0;
            total_in += n;
            if (first_read) {
                first_read = 0;
                /* Check magic for zstd */
                if (n >= 4) {
                    unsigned magic = (unsigned)inBuf[0] |
                                     ((unsigned)inBuf[1] << 8) |
                                     ((unsigned)inBuf[2] << 16) |
                                     ((unsigned)inBuf[3] << 24);
                    unsigned sk = magic & ZSTD_MAGIC_SKIPPABLE_MASK;
                    if (magic != ZSTD_MAGICNUMBER && sk != ZSTD_MAGIC_SKIPPABLE_START) {
                        fprintf(stderr, "zstd: %s: unsupported format \n",
                                src_name ? src_name : "stdin");
                        unsupported = 1;
                        status = -1;
                        break;
                    }
                }
            }
        }
        ZSTD_outBuffer output = { outBuf, outBufSize, 0 };
        size_t r = ZSTD_decompressStream(dctx, &output, &input);
        if (ZSTD_isError(r)) {
            fprintf(stderr, "zstd: %s: %s \n",
                    src_name ? src_name : "stdin",
                    ZSTD_getErrorName(r));
            status = -1;
            break;
        }
        last_ret = r;
        need_new_frame = (r == 0);
        if (output.pos > 0) {
            if (out) {
                if (fwrite(outBuf, 1, output.pos, out) != output.pos) {
                    fprintf(stderr, "zstd: error writing output: %s \n",
                            strerror(errno));
                    status = -1;
                    break;
                }
            }
            total_out += output.pos;
        }
    }
    free(inBuf); free(outBuf); ZSTD_freeDCtx(dctx);
    if (out_src_compressed) *out_src_compressed = total_in;
    if (out_dst_uncompressed) *out_dst_uncompressed = total_out;
    (void)unsupported;
    return status;
}

/* ------------ Print per-file progress summary ------------ */
static void print_progress_compress(const char *name, const char *out_name,
                                     unsigned long long src, unsigned long long dst) {
    char src_buf[32];
    char dst_buf[32];
    fmt_readable_size(src_buf, sizeof(src_buf), src);
    fmt_readable_size(dst_buf, sizeof(dst_buf), dst);
    if (verbosity < 2) return;
    if (src == 0) {
        fprintf(stderr, "%-20s :  (%s =>%s, %s) \n",
                name, src_buf, dst_buf, out_name);
    } else {
        double pct = 100.0 * (double)dst / (double)src;
        fprintf(stderr, "%-20s :%6.2f%%   (%s =>%s, %s) \n",
                name, pct, src_buf, dst_buf, out_name);
    }
}

static void print_progress_decompress(const char *name,
                                       unsigned long long dst) {
    if (verbosity < 2) return;
    fprintf(stderr, "%-20s : %llu bytes \n", name, dst);
}

/* ------------ Derive output name for compression ------------ */
static char *derive_comp_out(const char *input_name) {
    size_t n = strlen(input_name);
    char *out = malloc(n + 8);
    if (!out) return NULL;
    snprintf(out, n + 8, "%s.zst", input_name);
    return out;
}

/* ------------ Operate on one file ------------ */
static int operate_compress_file(const char *in_name) {
    FILE *in = NULL;
    const char *src_name = in_name;
    int is_stdin = (strcmp(in_name, "-") == 0);
    int src_size_known = 0;
    unsigned long long src_size = 0;
    if (is_stdin) {
        in = stdin;
        src_name = STDIN_NAME;
        if (stream_size >= 0) { src_size_known = 1; src_size = (unsigned long long)stream_size; }
    } else {
        struct stat st;
        if (stat(in_name, &st) < 0) {
            fprintf(stderr, "zstd: can't stat %s : %s -- ignored \n",
                    in_name, strerror(errno));
            return -1;
        }
        if (S_ISDIR(st.st_mode)) {
            fprintf(stderr, "zstd: %s is a directory -- ignored \n", in_name);
            return -1;
        }
        in = fopen(in_name, "rb");
        if (!in) {
            fprintf(stderr, "zstd: can't open %s : %s \n", in_name, strerror(errno));
            return -1;
        }
        if (S_ISREG(st.st_mode)) {
            src_size_known = 1;
            src_size = (unsigned long long)st.st_size;
        }
    }
    /* Determine output */
    FILE *out = NULL;
    char *derived = NULL;
    const char *out_name = NULL;
    int use_stdout = to_stdout;
    if (is_stdin && !output_file && !use_stdout) use_stdout = 1;
    if (use_stdout) {
        out = stdout;
        out_name = STDOUT_NAME;
    } else if (output_file) {
        out_name = output_file;
    } else {
        derived = derive_comp_out(in_name);
        out_name = derived;
    }
    if (!use_stdout) {
        if (!prompt_overwrite(out_name)) {
            if (in != stdin) fclose(in);
            free(derived);
            return -1;
        }
        out = fopen(out_name, "wb");
        if (!out) {
            fprintf(stderr, "zstd: can't open %s : %s \n", out_name, strerror(errno));
            if (in != stdin) fclose(in);
            free(derived);
            return -1;
        }
    } else {
        if (isatty(fileno(stdout)) && !force_flag) {
            fprintf(stderr,
                    "zstd: stdout is a console, aborting (use -f to force) \n");
            if (in != stdin) fclose(in);
            free(derived);
            return -1;
        }
    }
    unsigned long long osrc = 0, odst = 0;
    int rc = compress_stream(in, out, src_size_known, src_size, &osrc, &odst);
    if (in != stdin) fclose(in);
    if (out && out != stdout) fclose(out);
    if (rc == 0) {
        print_progress_compress(src_name, out_name, osrc, odst);
        if (rm_explicit && !is_stdin && !use_stdout) {
            if (unlink(in_name) != 0) {
                fprintf(stderr, "zstd: couldn't remove source %s : %s \n",
                        in_name, strerror(errno));
            }
        }
    } else {
        if (!use_stdout && out_name) unlink(out_name);
    }
    free(derived);
    return rc;
}

static int operate_decompress_file(const char *in_name) {
    FILE *in = NULL;
    const char *src_name = in_name;
    int is_stdin = (strcmp(in_name, "-") == 0);
    char *derived = NULL;
    const char *out_name = NULL;
    FILE *out = NULL;
    int use_stdout = to_stdout;
    if (is_stdin) {
        in = stdin;
        src_name = STDIN_NAME;
        if (!output_file) use_stdout = 1;
    } else {
        struct stat st;
        if (stat(in_name, &st) < 0) {
            fprintf(stderr, "zstd: can't stat %s : %s -- ignored \n",
                    in_name, strerror(errno));
            return -1;
        }
        if (S_ISDIR(st.st_mode)) {
            fprintf(stderr, "zstd: %s is a directory -- ignored \n", in_name);
            return -1;
        }
        in = fopen(in_name, "rb");
        if (!in) {
            fprintf(stderr, "zstd: can't open %s : %s \n", in_name, strerror(errno));
            return -1;
        }
    }
    if (use_stdout) {
        out = stdout;
        out_name = STDOUT_NAME;
    } else if (output_file) {
        out_name = output_file;
    } else {
        derived = strip_suffix(in_name);
        if (!derived) {
            fprintf(stderr,
                "zstd: %s: unknown suffix (.zst/.tzst/.gz/.tgz expected). "
                "Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n",
                in_name);
            if (in != stdin) fclose(in);
            return -1;
        }
        out_name = derived;
    }
    if (!test_mode && !use_stdout) {
        if (!prompt_overwrite(out_name)) {
            if (in != stdin) fclose(in);
            free(derived);
            return -1;
        }
        out = fopen(out_name, "wb");
        if (!out) {
            fprintf(stderr, "zstd: can't open %s : %s \n", out_name, strerror(errno));
            if (in != stdin) fclose(in);
            free(derived);
            return -1;
        }
    }
    if (test_mode) {
        out = NULL;
        out_name = NULL;
    }
    unsigned long long osrc = 0, odst = 0;
    int rc = decompress_stream(in, out, &osrc, &odst, src_name);
    if (in != stdin) fclose(in);
    if (out && out != stdout) fclose(out);
    if (rc == 0) {
        if (test_mode) {
            print_progress_decompress(src_name, odst);
        } else if (!use_stdout) {
            print_progress_decompress(src_name, odst);
            if (rm_explicit && !is_stdin) {
                if (unlink(in_name) != 0) {
                    fprintf(stderr, "zstd: couldn't remove source %s : %s \n",
                            in_name, strerror(errno));
                }
            }
        }
    } else {
        if (!test_mode && !use_stdout && out_name) unlink(out_name);
    }
    free(derived);
    return rc;
}

/* ------------ List mode ------------ */
static int list_one(const char *name) {
    FILE *f = fopen(name, "rb");
    if (!f) {
        fprintf(stderr, "zstd: can't open %s : %s \n", name, strerror(errno));
        return -1;
    }
    unsigned long long compressed = 0;
    unsigned long long uncompressed = 0;
    unsigned frames = 0;
    unsigned skips = 0;
    int has_check = 0;
    unsigned char hdr[18];
    while (1) {
        size_t n = fread(hdr, 1, 4, f);
        if (n == 0) break;
        if (n < 4) { fclose(f); return -1; }
        compressed += n;
        unsigned magic = hdr[0] | (hdr[1] << 8) | (hdr[2] << 16) | (hdr[3] << 24);
        if ((magic & ZSTD_MAGIC_SKIPPABLE_MASK) == ZSTD_MAGIC_SKIPPABLE_START) {
            unsigned char szBuf[4];
            if (fread(szBuf, 1, 4, f) != 4) { fclose(f); return -1; }
            compressed += 4;
            unsigned sz = szBuf[0] | (szBuf[1]<<8) | (szBuf[2]<<16) | (szBuf[3]<<24);
            /* skip sz bytes */
            if (fseek(f, sz, SEEK_CUR) != 0) { fclose(f); return -1; }
            compressed += sz;
            skips++;
            continue;
        }
        if (magic != ZSTD_MAGICNUMBER) {
            fprintf(stderr, "zstd: %s: not in zstd format \n", name);
            fclose(f); return -1;
        }
        /* Read more header bytes to decode */
        size_t toRead = 14; /* remaining bytes, max */
        if (fread(hdr + 4, 1, toRead, f) < 1) { fclose(f); return -1; }
        /* Determine header length */
        ZSTD_frameHeader zfh;
        size_t hret = ZSTD_getFrameHeader(&zfh, hdr, 4 + toRead);
        if (ZSTD_isError(hret) || hret > 0) {
            fprintf(stderr, "zstd: %s: error parsing frame header \n", name);
            fclose(f); return -1;
        }
        /* Skip remaining frame bytes by incremental decode using the known frameContentSize/block reading.
           But simpler: compute the rest using ZSTD_findFrameCompressedSize by reading the full frame. */
        /* Seek back to frame start and read whole frame */
        long frame_start = ftell(f) - (long)(4 + toRead);
        fseek(f, frame_start, SEEK_SET);
        /* Read all remaining bytes of file */
        long cur = ftell(f);
        fseek(f, 0, SEEK_END);
        long end = ftell(f);
        size_t rem = (size_t)(end - cur);
        fseek(f, cur, SEEK_SET);
        unsigned char *buf = malloc(rem);
        if (!buf) { fclose(f); return -1; }
        if (fread(buf, 1, rem, f) != rem) { free(buf); fclose(f); return -1; }
        size_t framesz = ZSTD_findFrameCompressedSize(buf, rem);
        if (ZSTD_isError(framesz)) {
            fprintf(stderr, "zstd: %s: error parsing frame: %s \n", name,
                    ZSTD_getErrorName(framesz));
            free(buf); fclose(f); return -1;
        }
        /* fix: compressed was double-incremented; reset and recompute */
        frames++;
        compressed = compressed - (4 + toRead);
        compressed += framesz;
        if (zfh.frameContentSize != ZSTD_CONTENTSIZE_UNKNOWN) {
            uncompressed += zfh.frameContentSize;
        }
        has_check |= zfh.checksumFlag;
        /* Seek past the frame */
        fseek(f, frame_start + (long)framesz, SEEK_SET);
        free(buf);
    }
    fclose(f);
    char cbuf[32], ubuf[32];
    fmt_readable_size(cbuf, sizeof(cbuf), compressed);
    fmt_readable_size(ubuf, sizeof(ubuf), uncompressed);
    double ratio = uncompressed ? (double)uncompressed / (double)compressed : 0.0;
    const char *chk = has_check ? "XXH64" : "None ";
    printf("%6u %6u  %s  %s  %5.3f  %s  %s\n",
           frames, skips, cbuf, ubuf, ratio, chk, name);
    return 0;
}

static int do_list(int argc_files, char **files) {
    if (argc_files == 0) {
        fprintf(stderr, "zstd: --list does not support reading from standard input \n");
        fprintf(stderr, "No files given \n");
        return 1;
    }
    printf("Frames  Skips  Compressed  Uncompressed  Ratio  Check  Filename\n");
    int err = 0;
    for (int i = 0; i < argc_files; i++) {
        if (list_one(files[i]) != 0) err = 1;
    }
    return err;
}

/* ------------ Argument parsing ------------ */
static int parse_uint(const char *s, int *out) {
    char *end;
    long v = strtol(s, &end, 10);
    if (end == s || *end != 0 || v < 0 || v > INT_MAX) return -1;
    *out = (int)v;
    return 0;
}

int main(int argc, char **argv) {
    (void)PROG;
    if (argc < 1) return 1;
    /* Detect unzstd / zstdcat invocation from argv[0] */
    const char *bn = strrchr(argv[0], '/');
    bn = bn ? bn + 1 : argv[0];
    if (strstr(bn, "unzstd")) decompress_mode = 1;
    if (strstr(bn, "zstdcat")) { decompress_mode = 1; to_stdout = 1; }
    if (strstr(bn, "zstdmt")) { nb_workers = 0; /* all cores */ }

    int mode_dict_train = 0;
    (void)mode_dict_train;
    int after_dash = 0;
    int n_files = 0;
    int cap = 16;
    char **files = calloc(cap, sizeof(char*));

    for (int i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (after_dash) {
            goto ADD_FILE;
        }
        if (a[0] != '-' || a[1] == 0) {
            /* File or single "-" */
ADD_FILE:
            if (n_files == cap) { cap *= 2; files = realloc(files, cap * sizeof(char*)); }
            files[n_files++] = (char*)a;
            continue;
        }
        /* Long options */
        if (a[1] == '-') {
            const char *opt = a + 2;
            if (*opt == 0) { after_dash = 1; continue; }
            if (strcmp(opt, "version") == 0) { print_version(stdout); return 0; }
            if (strcmp(opt, "help") == 0) { print_full_help(stdout); return 0; }
            if (strcmp(opt, "decompress") == 0 || strcmp(opt, "uncompress") == 0) { decompress_mode = 1; continue; }
            if (strcmp(opt, "stdout") == 0 || strcmp(opt, "to-stdout") == 0) { to_stdout = 1; keep = 1; continue; }
            if (strcmp(opt, "keep") == 0) { keep = 1; rm_explicit = 0; continue; }
            if (strcmp(opt, "rm") == 0) { rm_explicit = 1; continue; }
            if (strcmp(opt, "force") == 0) { force_flag = 1; continue; }
            if (strcmp(opt, "verbose") == 0) { verbosity++; continue; }
            if (strcmp(opt, "quiet") == 0) { verbosity--; continue; }
            if (strcmp(opt, "test") == 0) { test_mode = 1; decompress_mode = 1; continue; }
            if (strcmp(opt, "ultra") == 0) { ultra = 1; continue; }
            if (strcmp(opt, "adapt") == 0) { continue; }
            if (strcmp(opt, "single-thread") == 0) { single_thread = 1; nb_workers = 0; continue; }
            if (strcmp(opt, "no-check") == 0) { no_checksum = 1; continue; }
            if (strcmp(opt, "check") == 0) { no_checksum = 0; continue; }
            if (strcmp(opt, "no-dictID") == 0) { no_dictID = 1; continue; }
            if (strcmp(opt, "no-progress") == 0) { progress_flag = 0; continue; }
            if (strcmp(opt, "progress") == 0) { progress_flag = 1; continue; }
            if (strcmp(opt, "no-asyncio") == 0) { asyncio_flag = 0; continue; }
            if (strcmp(opt, "asyncio") == 0) { asyncio_flag = 1; continue; }
            if (strcmp(opt, "rsyncable") == 0) { rsyncable_flag = 1; continue; }
            if (strcmp(opt, "no-sparse") == 0) { sparse_mode = 0; continue; }
            if (strcmp(opt, "sparse") == 0) { sparse_mode = 1; continue; }
            if (strcmp(opt, "no-pass-through") == 0) { pass_through = 0; continue; }
            if (strcmp(opt, "pass-through") == 0) { pass_through = 1; continue; }
            if (strcmp(opt, "no-compress-literals") == 0) { continue; }
            if (strcmp(opt, "compress-literals") == 0) { continue; }
            if (strcmp(opt, "no-row-match-finder") == 0) { continue; }
            if (strcmp(opt, "row-match-finder") == 0) { continue; }
            if (strcmp(opt, "no-mmap-dict") == 0) { continue; }
            if (strcmp(opt, "mmap-dict") == 0) { continue; }
            if (strcmp(opt, "exclude-compressed") == 0) { continue; }
            if (strcmp(opt, "patch-apply") == 0) { decompress_mode = 1; continue; }
            if (strncmp(opt, "fast", 4) == 0) {
                if (opt[4] == 0) { fast_level = 1; continue; }
                if (opt[4] == '=') {
                    int v;
                    if (parse_uint(opt + 5, &v) == 0) { fast_level = v; continue; }
                }
                print_incorrect(a); return 1;
            }
            if (strncmp(opt, "long", 4) == 0) {
                if (opt[4] == 0) { long_enabled = 1; long_log = 27; continue; }
                if (opt[4] == '=') {
                    int v;
                    if (parse_uint(opt + 5, &v) == 0) { long_enabled = 1; long_log = v; continue; }
                }
                print_incorrect(a); return 1;
            }
            if (strncmp(opt, "format=", 7) == 0) {
                const char *v = opt + 7;
                if (strcmp(v, "zstd") == 0) continue;
                if (strcmp(v, "gzip") == 0) {
                    fprintf(stderr, "zstd: gzip format not supported in this build \n");
                    return 1;
                }
                if (strcmp(v, "xz") == 0 || strcmp(v, "lzma") == 0 || strcmp(v, "lz4") == 0) {
                    fprintf(stderr, "zstd: format %s not supported in this build \n", v);
                    return 1;
                }
                print_incorrect(a); return 1;
            }
            if (strncmp(opt, "memlimit=", 9) == 0 || strncmp(opt, "memory=", 7) == 0 || strncmp(opt, "memlimit-decompress=", 20) == 0) {
                /* accept and ignore precise parse */
                continue;
            }
            if (strncmp(opt, "jobsize=", 8) == 0) {
                /* ignore */
                continue;
            }
            if (strncmp(opt, "stream-size=", 12) == 0) {
                long long v = strtoll(opt + 12, NULL, 10);
                stream_size = v; continue;
            }
            if (strncmp(opt, "size-hint=", 10) == 0) {
                long long v = strtoll(opt + 10, NULL, 10);
                size_hint = v; continue;
            }
            if (strncmp(opt, "target-compressed-block-size=", 29) == 0) {
                continue;
            }
            if (strncmp(opt, "auto-threads=", 13) == 0) {
                continue;
            }
            if (strcmp(opt, "filelist") == 0) {
                if (++i >= argc) { print_incorrect(a); return 1; }
                /* TODO: read file list. For now, we accept and add lines. */
                FILE *fl = fopen(argv[i], "r");
                if (!fl) {
                    fprintf(stderr, "zstd: can't open filelist %s : %s \n", argv[i], strerror(errno));
                    return 1;
                }
                char line[4096];
                while (fgets(line, sizeof(line), fl)) {
                    size_t L = strlen(line);
                    while (L > 0 && (line[L-1] == '\n' || line[L-1] == '\r')) line[--L] = 0;
                    if (L == 0) continue;
                    if (n_files == cap) { cap *= 2; files = realloc(files, cap * sizeof(char*)); }
                    files[n_files++] = strdup(line);
                }
                fclose(fl);
                continue;
            }
            if (strcmp(opt, "output-dir-flat") == 0) {
                if (++i >= argc) { print_incorrect(a); return 1; }
                output_dir_flat = argv[i]; continue;
            }
            if (strcmp(opt, "output-dir-mirror") == 0) {
                if (++i >= argc) { print_incorrect(a); return 1; }
                output_dir_mirror = argv[i]; continue;
            }
            if (strcmp(opt, "trace") == 0) {
                if (++i >= argc) { print_incorrect(a); return 1; }
                trace_log = argv[i]; continue;
            }
            if (strncmp(opt, "patch-from=", 11) == 0) {
                dict_path = opt + 11; continue;
            }
            /* Unknown long option */
            print_incorrect(a);
            return 1;
        }
        /* Short options: may be combined like -df */
        for (int j = 1; a[j]; j++) {
            char c = a[j];
            switch (c) {
            case 'V': print_version(stdout); return 0;
            case 'h': print_short_help(stdout); return 0;
            case 'H': print_full_help(stdout); return 0;
            case 'd': decompress_mode = 1; break;
            case 'c': to_stdout = 1; keep = 1; break;
            case 'k': keep = 1; rm_explicit = 0; break;
            case 'f': force_flag = 1; break;
            case 'v': verbosity++; break;
            case 'q': verbosity--; break;
            case 'z': decompress_mode = 0; break;
            case 'l': list_mode = 1; break;
            case 't': test_mode = 1; decompress_mode = 1; break;
            case 'r': /* recursive - not implemented meaningfully */ break;
            case 'o': {
                const char *val;
                if (a[j+1]) { val = a + j + 1; j = (int)strlen(a) - 1; }
                else if (++i < argc) { val = argv[i]; }
                else { fprintf(stderr, "error: missing argument for -o \n"); return 1; }
                output_file = val;
                break;
            }
            case 'D': {
                const char *val;
                if (a[j+1]) { val = a + j + 1; j = (int)strlen(a) - 1; }
                else if (++i < argc) { val = argv[i]; }
                else { fprintf(stderr, "error: missing argument for -D \n"); return 1; }
                dict_path = val;
                break;
            }
            case 'M': {
                /* memory limit in MB - rest of arg is number */
                if (a[j+1]) {
                    int v;
                    if (parse_uint(a + j + 1, &v) == 0) { memory_limit_mb = v; j = (int)strlen(a) - 1; }
                    else { print_incorrect(a); return 1; }
                } else {
                    /* No numeric part - error */
                    fprintf(stderr, "error: missing argument for -M \n"); return 1;
                }
                break;
            }
            case 'T': {
                if (a[j+1]) {
                    int v;
                    if (parse_uint(a + j + 1, &v) == 0) { nb_workers = v; j = (int)strlen(a) - 1; }
                    else { print_incorrect(a); return 1; }
                } else {
                    fprintf(stderr, "error: missing argument for -T \n"); return 1;
                }
                break;
            }
            case 'b':
            case 'e':
            case 'i':
            case 'B':
            case 'p':
            case 'S':
            case 'P':
                /* Benchmark flags - accept but ignore */
                if (a[j+1] && isdigit((unsigned char)a[j+1])) {
                    j = (int)strlen(a) - 1;
                }
                break;
            case '-': {
                /* Looking at something like --foo embedded? Should not happen. */
                fprintf(stderr, "error: command cannot be separated from its argument by another command \n");
                return 1;
            }
            default:
                if (isdigit((unsigned char)c)) {
                    /* Parse numeric level */
                    int lvl = 0;
                    while (a[j] && isdigit((unsigned char)a[j])) {
                        lvl = lvl * 10 + (a[j] - '0');
                        j++;
                    }
                    j--;
                    comp_level = lvl;
                    break;
                }
                print_incorrect(a);
                return 1;
            }
        }
    }

    /* Post-process: if test, keep stdin behavior */
    if (list_mode) {
        if (n_files == 0) {
            fprintf(stderr, "zstd: --list does not support reading from standard input \n");
            fprintf(stderr, "No files given \n");
            return 1;
        }
        return do_list(n_files, files);
    }

    if (dict_path) {
        if (load_dictionary() != 0) return 1;
    }

    /* Multi-input into single -o: if compressing, ask; if decompressing, concat (zstd supports multi-frame concat) */
    if (output_file && n_files > 1 && !decompress_mode) {
        if (!force_flag) {
            fprintf(stderr,
                "zstd: WARNING: all input files will be processed and concatenated into a single output file: %s \n", output_file);
            fprintf(stderr,
                "The concatenated output CANNOT regenerate original file names nor directory structure. \n");
            fprintf(stderr, "Proceed? (y/n): ");
            if (!isatty(fileno(stdin))) {
                fprintf(stderr, "Aborting... \n");
                return 1;
            }
            int c = fgetc(stdin);
            int first = c;
            while (c != '\n' && c != EOF) c = fgetc(stdin);
            if (first != 'y' && first != 'Y') {
                fprintf(stderr, "Aborting... \n");
                return 1;
            }
        }
    }

    /* No files: read from stdin */
    if (n_files == 0) {
        if (isatty(fileno(stdin)) && !force_flag) {
            /* same as short help with program name */
            print_short_help(stdout);
            return 0;
        }
        /* Add a single "-" representing stdin */
        if (n_files == cap) { cap *= 2; files = realloc(files, cap * sizeof(char*)); }
        files[n_files++] = (char*)"-";
    }

    /* Multiple files summary */
    int err = 0;
    unsigned long long total_src = 0, total_dst = 0;
    int ok_count = 0;
    for (int i = 0; i < n_files; i++) {
        const char *in_name = files[i];
        int rc;
        if (decompress_mode) {
            if (strcmp(in_name, "-") != 0 && !file_exists(in_name)) {
                fprintf(stderr, "zstd: can't stat %s : %s -- ignored \n",
                        in_name, strerror(errno));
                err = 1;
                continue;
            }
            /* Check suffix unless -o, -c or stdin, or test */
            if (!output_file && !to_stdout && !test_mode && strcmp(in_name, "-") != 0) {
                if (!strip_suffix(in_name)) {
                    fprintf(stderr,
                        "zstd: %s: unknown suffix (.zst/.tzst/.gz/.tgz expected). "
                        "Can't derive the output file name. Specify it with -o dstFileName. Ignoring.\n",
                        in_name);
                    err = 1;
                    continue;
                }
            }
            rc = operate_decompress_file(in_name);
        } else {
            rc = operate_compress_file(in_name);
        }
        if (rc != 0) err = 1;
        else ok_count++;
    }
    (void)total_src; (void)total_dst;

    /* For multiple file compression, show summary */
    if (!decompress_mode && n_files > 1 && ok_count > 1 && verbosity >= 2 && !output_file && !to_stdout) {
        /* Compute totals from the files themselves */
        unsigned long long srcTot = 0, dstTot = 0;
        for (int i = 0; i < n_files; i++) {
            struct stat st;
            if (stat(files[i], &st) == 0) srcTot += (unsigned long long)st.st_size;
            char *o = derive_comp_out(files[i]);
            if (o) {
                struct stat st2;
                if (stat(o, &st2) == 0) dstTot += (unsigned long long)st2.st_size;
                free(o);
            }
        }
        double pct = srcTot ? (100.0 * (double)dstTot / (double)srcTot) : 0.0;
        fprintf(stderr,
            "%3d files compressed : %6.2f%% (%6llu   B =>%7llu   B)\n",
            ok_count, pct, srcTot, dstTot);
    }

    free(files);
    free(dict_data);
    return err ? 1 : 0;
}
